    HttpApiEndpoint.get("orderDraftsList", "/order_drafts", { query: OrderDraftsListQuery, headers: OrderDraftsListHeaders, success: OrderDraftsList200, error: [OrderDraftsList401.pipe(HttpApiSchema.status(401)), OrderDraftsList403.pipe(HttpApiSchema.status(403))] })
