    HttpApiEndpoint.get("orderDraftsGet", "/order_drafts/{id}", { params: OrderDraftsGetPathParams, success: OrderDraftsGet200, error: [OrderDraftsGet401.pipe(HttpApiSchema.status(401)), OrderDraftsGet403.pipe(HttpApiSchema.status(403)), OrderDraftsGet404.pipe(HttpApiSchema.status(404))] })
      .middleware(BearerAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "orderDrafts.get")
      .annotate(OpenApi.Summary, "Get order draft details")
      .annotate(OpenApi.Description, "Returns the order draft row. The order draft’s own customer sees the full record including `field_values`; workspace members of the parent offer see the row with `field_values` omitted."),
    HttpApiEndpoint.post("orderDraftsCancel", "/order_drafts/{id}:cancel", { params: OrderDraftsCancelPathParams, headers: OrderDraftsCancelHeaders, success: OrderDraftsCancel200, error: [OrderDraftsCancel401.pipe(HttpApiSchema.status(401)), OrderDraftsCancel403.pipe(HttpApiSchema.status(403)), OrderDraftsCancel404.pipe(HttpApiSchema.status(404)), OrderDraftsCancel409.pipe(HttpApiSchema.status(409)), OrderDraftsCancel422.pipe(HttpApiSchema.status(422))] })
      .middleware(BearerAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "orderDrafts.cancel")
      .annotate(OpenApi.Summary, "Cancel order draft")
      .annotate(OpenApi.Description, "Terminates an in-flight order draft, returning the updated record. Allowed for the order draft’s own customer or any member of the parent offer’s workspace. Idempotent — cancelling a terminated order draft returns it unchanged. Allocated cluster resources are released and any in-flight install workflow is terminated; previously-completed work is NOT undone."),
    HttpApiEndpoint.post("orderDraftsClaim", "/order_drafts/{id}:claim", { params: OrderDraftsClaimPathParams, headers: OrderDraftsClaimHeaders, payload: OrderDraftsClaimRequestJson, success: OrderDraftsClaim200, error: [OrderDraftsClaim401.pipe(HttpApiSchema.status(401)), OrderDraftsClaim403.pipe(HttpApiSchema.status(403)), OrderDraftsClaim404.pipe(HttpApiSchema.status(404)), OrderDraftsClaim409.pipe(HttpApiSchema.status(409)), OrderDraftsClaim422.pipe(HttpApiSchema.status(422))] })
